// Name-based index for fallback matching
const routesByName = {};
for (const [id, r] of Object.entries(routesBySignature)) {
  routesByName[r.name.toLowerCase()] = { ...r, signatureId: id };
}

function lookupRoute(routeId, routeName) {
  // Try direct ID match first (works when Zwift routeId === zwifthacks signature)
  if (routeId && routesBySignature[routeId]) return routesBySignature[routeId];
  // Fallback to name match
  if (routeName) {
    const key = routeName.toLowerCase().trim();
    if (routesByName[key]) return routesByName[key];
  }
  return null;
}

module.exports = { routesBySignature, routesByName, lookupRoute };
